import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxDivider,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'attention' | 'over' | 'archived';

type Project = {
  id: string;
  name: string;
  owner: string;
  quotaUsage: number;
  status: ProjectStatus;
};

const STATUS_META: Record<
  ProjectStatus,
  { label: string; tone: 'success' | 'warning' | 'danger' | 'alt' }
> = {
  active: { label: 'В норме', tone: 'success' },
  attention: { label: 'Близко к лимиту', tone: 'warning' },
  over: { label: 'Превышение', tone: 'danger' },
  archived: { label: 'В архиве', tone: 'alt' },
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'attention', 'over', 'archived'];

const PROJECTS: Project[] = [
  { id: 'p-01', name: 'Витрина каталога', owner: 'Команда Retail', quotaUsage: 38, status: 'active' },
  { id: 'p-02', name: 'Платёжный шлюз', owner: 'Команда Payments', quotaUsage: 81, status: 'attention' },
  { id: 'p-03', name: 'Аналитика воронки', owner: 'Команда Growth', quotaUsage: 114, status: 'over' },
  { id: 'p-04', name: 'Мобильный клиент', owner: 'Команда Mobile', quotaUsage: 52, status: 'active' },
  { id: 'p-05', name: 'Складской учёт', owner: 'Команда Logistics', quotaUsage: 77, status: 'attention' },
  { id: 'p-06', name: 'Рассылки и триггеры', owner: 'Команда CRM', quotaUsage: 23, status: 'archived' },
  { id: 'p-07', name: 'Поиск по документам', owner: 'Команда Search', quotaUsage: 96, status: 'over' },
  { id: 'p-08', name: 'Личный кабинет', owner: 'Команда Account', quotaUsage: 45, status: 'active' },
  { id: 'p-09', name: 'Импорт прайсов', owner: 'Команда Integrations', quotaUsage: 68, status: 'attention' },
  { id: 'p-10', name: 'Старый биллинг', owner: 'Команда Platform', quotaUsage: 12, status: 'archived' },
  { id: 'p-11', name: 'Очереди событий', owner: 'Команда Platform', quotaUsage: 88, status: 'attention' },
  { id: 'p-12', name: 'Отчёты для финансов', owner: 'Команда Finance', quotaUsage: 31, status: 'active' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [statusFilter, setStatusFilter] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const visibleProjects = useMemo(
    () =>
      statusFilter.length === 0
        ? PROJECTS
        : PROJECTS.filter((project) => statusFilter.includes(project.status)),
    [statusFilter],
  );

  const pageCount = Math.max(1, Math.ceil(visibleProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const pageItems = visibleProjects.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const toggleStatus = (status: ProjectStatus) => {
    setStatusFilter((previous) =>
      previous.includes(status)
        ? previous.filter((item) => item !== status)
        : [...previous, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setStatusFilter([]);
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)', color: 'var(--jx-text)' }}>
          Расход по проектам
        </h2>
        <p style={{ margin: 0, color: 'var(--jx-text-2)' }}>
          Заполненность квоты за текущий период. Найдено проектов: {visibleProjects.length}.
        </p>
      </header>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignItems: 'center' }}>
        {STATUS_ORDER.map((status) => {
          const isActive = statusFilter.includes(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onRemove={() => toggleStatus(status)}
              onClick={() => toggleStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
        {statusFilter.length > 0 && (
          <JxButton variant="ghost" size="sm" onClick={resetFilters}>
            Сбросить
          </JxButton>
        )}
      </div>

      {pageItems.length === 0 ? (
        <JxEmptyState
          title="Под фильтры ничего не подошло"
          message="Ни один проект не соответствует выбранным статусам. Снимите часть фильтров, чтобы увидеть список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
            }}
          >
            {pageItems.map((project, index) => (
              <li key={project.id}>
                {index > 0 && <JxDivider />}
                <div
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 0',
                  }}
                >
                  <JxProgressCircle value={project.quotaUsage} showValue />
                  <div
                    style={{
                      display: 'flex',
                      flexDirection: 'column',
                      gap: '2px',
                      flex: 1,
                      minWidth: 0,
                    }}
                  >
                    <span style={{ color: 'var(--jx-text)' }}>{project.name}</span>
                    <span style={{ color: 'var(--jx-text-3)', fontSize: '0.875em' }}>
                      {project.owner}
                    </span>
                  </div>
                  <JxBadge tone={STATUS_META[project.status].tone} dot>
                    {STATUS_META[project.status].label}
                  </JxBadge>
                </div>
              </li>
            ))}
          </ul>

          {pageCount > 1 && (
            <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
          )}
        </div>
      )}
    </section>
  );
}

